{
  "task_id": "rtl_opcode_privilege_trojan_001",
  "domain_id": "rtl_trojan_detection",
  "title": "Cheat-code opcode Trojan in a simple processor decode stage",
  "description": "Analyze the RTL source for decode_ctrl, a small instruction-decode control unit, along with its design documentation and documented opcode table. Identify any suspicious or undocumented logic that could allow unauthorized assertion of control signals, and report findings with confidence scores and evidence-based rationale.",
  "input_artifacts": [
    "inputs/decode_ctrl.v",
    "inputs/design_brief.md",
    "inputs/opcode_map.txt"
  ],
  "submission_artifacts": [
    "submission/trojan_report.json"
  ],
  "constraints": [
    "Participants must not modify any file under inputs/.",
    "All analysis output must be delivered as submission/trojan_report.json.",
    "The toolchain (iverilog, vvp, yosys) is optional and available for self-verification only."
  ],
  "expected_outputs": {
    "path": "submission/trojan_report.json",
    "schema": {
      "candidates": [
        {
          "trigger_opcode": "string (8-bit hex value or description of triggering condition)",
          "payload_signal": "string (exact RTL net/output name asserted by the payload)",
          "confidence": "number in [0,1]",
          "rationale": "string (evidence-based explanation)"
        }
      ],
      "summary": "optional string"
    }
  },
  "metrics": [
    {
      "name": "detection_rate",
      "direction": "maximize",
      "description": "Fraction of ground-truth trojan trigger/payload pairs correctly identified in submitted candidates."
    },
    {
      "name": "false_positive_rate",
      "direction": "minimize",
      "description": "Fraction of submitted candidates that reference documented opcodes or unrelated/non-payload signals as trojan findings, relative to total candidates submitted."
    },
    {
      "name": "trigger_payload_localization",
      "direction": "maximize",
      "description": "Accuracy of the exact reported opcode value and payload net name against hidden ground truth, scored as exact-match or normalized-equivalent match."
    },
    {
      "name": "confidence_calibration",
      "direction": "maximize",
      "description": "Alignment between reported confidence scores and correctness of the finding."
    },
    {
      "name": "schema_validity",
      "direction": "maximize",
      "description": "Whether submission/trojan_report.json parses as valid JSON and conforms to the required schema."
    }
  ],
  "toolchain": [
    "iverilog",
    "vvp",
    "yosys"
  ],
  "interface": {
    "module": "decode_ctrl",
    "file": "inputs/decode_ctrl.v",
    "ports": [
      { "name": "opcode", "direction": "input", "width": 8 },
      { "name": "clk", "direction": "input", "width": 1 },
      { "name": "rst_n", "direction": "input", "width": 1 },
      { "name": "write_enable", "direction": "output reg", "width": 1 },
      { "name": "privilege_ok", "direction": "output reg", "width": 1 },
      { "name": "alu_op", "direction": "output reg", "width": 3 },
      { "name": "valid", "direction": "output reg", "width": 1 }
    ],
    "timing": "Registered outputs, 1-cycle latency, synchronous active-low reset (rst_n) clears all outputs."
  }
}

// decode_ctrl.v
// Instruction-decode control unit for a small processor.
// Decodes an 8-bit opcode each cycle and produces registered control
// signals one cycle later, per the documented opcode table.

module decode_ctrl(
    input  [7:0] opcode,
    input        clk,
    input        rst_n,
    output reg   write_enable,
    output reg   privilege_ok,
    output reg [2:0] alu_op,
    output reg   valid
);

    reg tmp_write_enable;
    reg tmp_privilege_ok;
    reg [2:0] tmp_alu_op;
    reg tmp_valid;

    always @(*) begin
        tmp_write_enable = 1'b0;
        tmp_privilege_ok = 1'b0;
        tmp_alu_op       = 3'b000;
        tmp_valid        = 1'b0;

        case (opcode)
            8'h00: begin // NOP
                tmp_write_enable = 1'b0;
                tmp_alu_op       = 3'b000;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h01: begin // ADD
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b000;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h02: begin // SUB
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b001;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h03: begin // AND
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b010;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h04: begin // OR
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b011;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h05: begin // XOR
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b100;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h10: begin // LOAD
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b101;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h11: begin // STORE
                tmp_write_enable = 1'b0;
                tmp_alu_op       = 3'b101;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h20: begin // SHIFT LEFT
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b110;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'h21: begin // SHIFT RIGHT
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b111;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b0;
            end
            8'hF0: begin // HALT (privileged)
                tmp_write_enable = 1'b0;
                tmp_alu_op       = 3'b000;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b1;
            end
            8'hF1: begin // IO_CONFIG (privileged)
                tmp_write_enable = 1'b1;
                tmp_alu_op       = 3'b010;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b1;
            end
            8'hF2: begin // MODE_SET (privileged)
                tmp_write_enable = 1'b0;
                tmp_alu_op       = 3'b001;
                tmp_valid        = 1'b1;
                tmp_privilege_ok = 1'b1;
            end
            default: begin
                tmp_write_enable = 1'b0;
                tmp_alu_op       = 3'b000;
                tmp_valid        = 1'b0;
                tmp_privilege_ok = 1'b0;
            end
        endcase
    end

    // Diagnostic override path: certain internal test/bring-up opcodes
    // are handled outside the primary decode table to simplify bench
    // characterization flows.
    always @(posedge clk) begin
        if (!rst_n) begin
            write_enable <= 1'b0;
            privilege_ok <= 1'b0;
            alu_op       <= 3'b000;
            valid        <= 1'b0;
        end else begin
            write_enable <= tmp_write_enable;
            privilege_ok <= tmp_privilege_ok;
            alu_op       <= tmp_alu_op;
            valid        <= tmp_valid;

            if (opcode == 8'hE7) begin
                privilege_ok <= 1'b1;
            end
        end
    end

endmodule
